const t=(value:string,lang:'ru'|'kk')=>lang==='kk'?(copy[value]||localize(value,true) as string):localize(value,false) as string;
const roles:Role[]=['coordinator','analyst','inspector','resident'];
const roleLabel:Record<Role,string>={coordinator:'Координатор',analyst:'Аналитик',inspector:'Инспектор',resident:'Житель'};
const pageDefaults:Record<Role,Page>={coordinator:'overview',analyst:'analytics',inspector:'tasks',resident:'public'};
const nav:Record<Role,{page:Page;title:string;icon:React.ComponentType<{size?:number}>}[]>={
 coordinator:[{page:'overview',title:'Обзор',icon:LayoutDashboard},{page:'map',title:'Карта мониторинга',icon:MapPin},{page:'tasks',title:'Полевые задачи',icon:ClipboardList},{page:'reports',title:'Публичный отчёт',icon:FileText}],
 analyst:[{page:'analytics',title:'Аналитика цен',icon:BarChart3},{page:'data',title:'Очистка данных',icon:Filter},{page:'catalog',title:'Каталог СЗПТ',icon:ShoppingBasket},{page:'reports',title:'Публичный отчёт',icon:FileText}],
 inspector:[{page:'tasks',title:'Моя очередь',icon:ClipboardList},{page:'capture',title:'Внести замер',icon:Plus},{page:'data',title:'Очистка данных',icon:Upload}],
 resident:[{page:'public',title:'Публичная панель',icon:LayoutDashboard},{page:'reports',title:'Публичный отчёт',icon:FileText},{page:'catalog',title:'Каталог СЗПТ',icon:ShoppingBasket}],
};
const loc=(value:string,lang:'ru'|'kk')=>t(value,lang);
const safeProduct=(name:string)=>products.find(p=>p.name===name)||products[5];
const median=(a:number[])=>{if(!a.length)return 0;const s=[...a].sort((x,y)=>x-y),m=Math.floor(s.length/2);return s.length%2?s[m]:(s[m-1]+s[m])/2};
const number=(n:number)=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(n);
const statusLabel=(s:string,lang:'ru'|'kk')=>{const map:Record<string,string>={'Жаңа':'Новая','Тағайындалды':'Назначена','Жұмыста':'В работе','Талдауды күтуде':'Ожидает анализа','Жабық':'Закрыта'};return loc(map[s]||s,lang)};
const districtLabel=(s:string,lang:'ru'|'kk')=>{const ru:Record<string,string>={'Қала орталығы':'Центр города','Теміржол маңы':'Железнодорожный район','Сырдария ауданы':'Сырдарьинский район','Орталық':'Центральный район','Арай':'Арай','Мерей':'Мерей','Титов':'Титов','Тасбөгет':'Тасбугет'};const kk:Record<string,string>={'Қала орталығы':'Қала орталығы','Теміржол маңы':'Теміржол маңы','Сырдария ауданы':'Сырдария ауданы','Орталық':'Орталық','Арай':'Арай','Мерей':'Мерей','Титов':'Титов','Тасбөгет':'Тасбөгет'};return (lang==='kk'?kk:ru)[s]||s};
