 const catalog=useMemo(()=>products.filter(p=>(categoryFilter==='all'||p.category===categoryFilter)&&(!query||p.name.toLowerCase().includes(query.toLowerCase())||(localize(p.name,true) as string).toLowerCase().includes(query.toLowerCase()))),[categoryFilter,query]);
 const chart=useMemo(()=>{const latest=visibleForProduct.map(x=>x.date).sort().at(-1);const cutoff=latest?new Date(new Date(latest+'T00:00:00Z').getTime()-(Number(period)-1)*86400000).toISOString().slice(0,10):'';return visibleForProduct.filter(x=>(!cutoff||x.date>=cutoff)&&(districtFilter==='all'||locations.find(l=>l.store.name===x.store)?.store.district===districtFilter)).reduce((a,o)=>{(a[o.date]??=[]).push(o.unitPrice);return a},{} as Record<string,number[]>);},[visibleForProduct,period,districtFilter]);
 const chartDays=Object.keys(chart).sort();
 const reportRows=products.slice(0,10).map(p=>{const rows=validObs.filter(x=>x.product===p.name);return{product:p.name,unit:p.unit,median:rows.length>=3?median(rows.map(x=>x.unitPrice)):0,count:rows.length}});
 const cityRows=validObs.filter(o=>o.date>='2026-10-16'&&stores.some(st=>st.name===o.store));
 const districtBasket=products.slice(0,10).map(p=>{const all=cityRows.filter(o=>o.product===p.name);const local=all.filter(o=>stores.find(s=>s.name===o.store)?.district===forecastDistrict);const todayLocal=local.filter(o=>o.date==='2026-11-14');const todayAll=all.filter(o=>o.date==='2026-11-14');const price=todayLocal.length?median(todayLocal.map(o=>o.unitPrice)):local.length?median(local.map(o=>o.unitPrice)):0;const city=todayAll.length?median(todayAll.map(o=>o.unitPrice)):all.length?median(all.map(o=>o.unitPrice)):0;const sorted=local.slice().sort((a,b)=>a.date.localeCompare(b.date));const first=sorted.filter(o=>o.date<='2026-11-07');const last=sorted.filter(o=>o.date>='2026-11-08');const change=first.length&&last.length?(median(last.map(o=>o.unitPrice))-median(first.map(o=>o.unitPrice)))/7:0;const min=local.length?Math.min(...local.map(o=>o.unitPrice)):0;const max=local.length?Math.max(...local.map(o=>o.unitPrice)):0;const cheapest=stores.map(st=>({name:st.name,values:cityRows.filter(o=>o.product===p.name&&o.store===st.name&&o.date==='2026-11-14').map(o=>o.unitPrice)})).filter(x=>x.values.length).sort((a,b)=>median(a.values)-median(b.values))[0]?.name||'—';return{product:p.name,unit:p.unit,price,city,delta:city?(price-city)/city*100:0,min,max,cheapest,forecast:Math.max(0,Math.round(price+change*7))}});
 const cheapestBasket=stores.map(st=>({district:st.district,total:products.slice(0,10).reduce((sum,prod)=>{const vals=cityRows.filter(o=>o.product===prod.name&&o.store===st.name).map(o=>o.unitPrice);return sum+(vals.length?median(vals):0)},0)})).sort((a,b)=>a.total-b.total)[0];
 const meanBasket=districtBasket.reduce((sum,r)=>sum+r.price,0);const cityBasket=districtBasket.reduce((sum,r)=>sum+r.city,0);
 const activityDays=Array.from({length:Number(activityPeriod)},(_,i)=>{const date=new Date(Date.UTC(2026,10,15-Number(activityPeriod)+i)).toISOString().slice(0,10);const rows=cityRows.filter(o=>o.date===date);return{date,stores:new Set(rows.map(o=>o.store)).size,observations:rows.length}});
 const visitedStores=new Set(cityRows.filter(o=>o.date>=(activityPeriod==='7'?'2026-11-08':'2026-10-16')).map(o=>o.store)).size;
 const show=(s:string)=>setToast(s);
