 const chartPath=periodRows.length?periodRows.map((p,i)=>`${i?'L':'M'} ${periodRows.length===1?50:20+i*560/(periodRows.length-1)} ${180-Math.max(0,Math.min(1,(p.v-160)/300))*150}`).join(' '):'';
 const heading=page==='overview'?'Сводка мониторинга':nav[role].find(n=>n.page===page)?.title||'Сводка мониторинга';

